// Builder pattern with types
class QueryBuilder {
  private query = "";

  select(fields: string[]) {
    this.query += `SELECT ${fields.join(", ")} `;
    return this;
  }

  from(table: string) {
    this.query += `FROM ${table} `;
    return this;
  }

  where(condition: string) {
    this.query += `WHERE ${condition}`;
    return this;
  }

  build(): string {
    return this.query.trim();
  }
}

const sql = new QueryBuilder()
